import{_ as o,a0 as l,w as p,s as g,ao as a,I as i,x as n,a1 as r,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Gnome 中共享电脑屏幕 | LCTT x X-CMD","titleTemplate":false,"description":"在 Gnome 中共享电脑屏幕 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Gnome 中共享电脑屏幕 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Gnome 中共享电脑屏幕 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220128 Sharing the computer screen in Gnome","title":"在 Gnome 中共享电脑屏幕","tag":"202202","desc":""},"relativePath":"202202/20220128 Sharing the computer screen in Gnome.md","filePath":"[post].md"}'),m={name:"202202/20220128 Sharing the computer screen in Gnome.md"};function d(u,t,h,b,f,c){const e=l("Link");return p(),g("div",null,[t[22]||(t[22]=a(`<h1 id="在-gnome-中共享电脑屏幕" tabindex="-1">在 Gnome 中共享电脑屏幕 <a class="header-anchor" href="#在-gnome-中共享电脑屏幕" aria-label="Permalink to “在 Gnome 中共享电脑屏幕”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202202/11/101112soc722i55ut7r6nq.jpg" alt=""></p><p>你不希望别人能够监视甚至控制你的电脑，你通常会努力使用各种安全机制来切断任何此类企图。然而，有时会出现这样的情况：你迫切需要一个朋友，或一个专家来帮助你解决电脑问题，但他们并不同时在同一地点。你如何向他们展示呢？你应该拿着你的手机，拍下你的屏幕照片，然后发给他们吗？你应该录制一个视频吗？当然不是。你可以与他们分享你的屏幕，并可能让他们远程控制你的电脑一段时间。在这篇文章中，我将介绍如何在 Gnome 中允许共享电脑屏幕。</p><h3 id="设置服务器以共享屏幕" tabindex="-1">设置服务器以共享屏幕 <a class="header-anchor" href="#设置服务器以共享屏幕" aria-label="Permalink to “设置服务器以共享屏幕”">​</a></h3><p><strong>服务器</strong> 是一台提供（服务）一些内容的计算机，其他计算机（<strong>客户端</strong>）将消费这些内容。在本文中，服务器运行的是 <strong>Fedora Workstation</strong> 和标准的 <strong>Gnome 桌面</strong>。</p><h4 id="打开-gnome-屏幕共享" tabindex="-1">打开 Gnome 屏幕共享 <a class="header-anchor" href="#打开-gnome-屏幕共享" aria-label="Permalink to “打开 Gnome 屏幕共享”">​</a></h4><p>默认情况下，Gnome 中共享计算机屏幕的功能是 <strong>关闭</strong> 的。要使用它，你需要把它打开：</p><ol><li>启动 <ruby>Gnome 控制中心<rt>Gnome Control Center</rt></ruby>。</li><li>点击 <ruby>共享<rt>Sharing</rt></ruby> 标签。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/settings_sharing_off.png" alt="Sharing switched off"></li><li>用右上角的滑块打开共享。</li><li>单击 <ruby>屏幕共享<rt>Screen sharing</rt></ruby>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/settings_sharing_on.png" alt="Sharing switched on"></li><li>用窗口左上角的滑块打开屏幕共享。</li><li>如果你希望能够从客户端控制屏幕，请勾选 <ruby>允许连接控制屏幕<rt>Allow connections to control the screen</rt></ruby>。不勾选这个按钮访问共享屏幕只允许 <ruby>仅浏览<rt>view-only</rt></ruby>。</li><li>如果你想手动确认所有传入的连接，请选择 <ruby>新连接必须请求访问<rt>New connections must ask for access</rt></ruby>。</li><li>如果你想允许知道密码的人连接（你不会被通知），选择 <ruby>需要密码<rt>Require a password</rt></ruby> 并填写密码。密码的长度只能是 8 个字符。</li><li>勾选 <ruby>显示密码<rt>Show password</rt></ruby> 以查看当前的密码是什么。为了多一点保护，不要在这里使用你的登录密码，而是选择一个不同的密码。</li><li>如果你有多个网络可用，你可以选择在哪个网络上访问该屏幕。</li></ol><h3 id="设置客户端以显示远程屏幕" tabindex="-1">设置客户端以显示远程屏幕 <a class="header-anchor" href="#设置客户端以显示远程屏幕" aria-label="Permalink to “设置客户端以显示远程屏幕”">​</a></h3><p><strong>客户端</strong> 是一台连接到由服务器提供的服务（或内容）的计算机。本演示还将在客户端上运行 <strong>Fedora Workstation</strong>，但如果它运行一个 VNC 客户端，操作系统实际上应该不太重要。</p><h4 id="检查可见性" tabindex="-1">检查可见性 <a class="header-anchor" href="#检查可见性" aria-label="Permalink to “检查可见性”">​</a></h4><p>在 Gnome 中，服务器和客户端之间共享计算机屏幕需要一个有效的网络连接，以及它们之间可见的“路由”。如果你不能建立这样的连接，你将无法查看或控制服务器的共享屏幕，这里描述的整个过程将无法工作。</p><p>为了确保连接的存在，找出服务器的 IP 地址。</p><p>启动 <ruby>Gnome 控制中心<rt>Gnome Control Center</rt></ruby>，又称 <ruby>设置<rt>Settings</rt></ruby>。使用右上角的<strong>菜单</strong>，或<strong>活动</strong>模式。当在<strong>活动</strong>中时，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>settings</span></span></code></pre></div><p>并点击相应的图标。</p><p>选择 <ruby>网络<rt>Network</rt></ruby> 标签。</p><p>点击<strong>设置按钮</strong>（齿轮）以显示你的网络配置文件的参数。</p><p>打开 <ruby>详情<rt>Details</rt></ruby>标签，查看你的计算机的 IP 地址。</p><p>进入 <strong>你的客户端的</strong> 终端（你想从它连接到别的计算机），使用 <code>ping</code> 命令找出客户和服务器之间是否有连接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping -c 5 192.168.122.225</span></span></code></pre></div><p>检查该命令的输出。如果它与下面的例子相似，说明计算机之间的连接存在。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PING 192.168.122.225 (192.168.122.225) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=1 ttl=64 time=0.383 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=2 ttl=64 time=0.357 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=3 ttl=64 time=0.322 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=4 ttl=64 time=0.371 ms</span></span>
<span class="line"><span>64 bytes from 192.168.122.225: icmp_seq=5 ttl=64 time=0.319 ms</span></span>
<span class="line"><span>--- 192.168.122.225 ping statistics ---</span></span>
<span class="line"><span>5 packets transmitted, 5 received, 0% packet loss, time 4083ms</span></span>
<span class="line"><span>rtt min/avg/max/mdev = 0.319/0.350/0.383/0.025 ms</span></span></code></pre></div><p>如果两台计算机存在同一个子网中，例如在你的家里或办公室，你可能不会遇到任何问题，但当你的服务器没有<strong>公共 IP 地址</strong>，无法从外部互联网上看到时，可能会出现问题。除非你是互联网接入点的唯一管理员，否则你可能需要就你的情况向你的管理员或你的 ISP 咨询。请注意，将你的计算机暴露在外部互联网上始终是一个有风险的策略，你<strong>必须充分注意</strong>保护你的计算机免受不必要的访问。</p><h4 id="安装-vnc-客户端-remmina" tabindex="-1">安装 VNC 客户端（Remmina） <a class="header-anchor" href="#安装-vnc-客户端-remmina" aria-label="Permalink to “安装 VNC 客户端（Remmina）”">​</a></h4><p>Remmina 是一个图形化的远程桌面客户端，你可以使用多种协议连接到远程服务器，如 VNC、Spice 或 RDP。Remmina 可以从 Fedora 仓库中获得，所以你可以用 <code>dnf</code> 命令或 <ruby>软件中心<rt>Software</rt></ruby> 来安装它，以你喜欢的方式为准。使用 <code>dnf</code>，下面的命令将安装该软件包和几个依赖项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install remmina</span></span></code></pre></div><h4 id="连接到服务器" tabindex="-1">连接到服务器 <a class="header-anchor" href="#连接到服务器" aria-label="Permalink to “连接到服务器”">​</a></h4><p>如果服务器和客户端之间有连接，请确保以下情况：</p><ol><li>计算机正在运行。</li><li>Gnome 会话正在运行。</li><li>启用了屏幕共享的用户已经登录。</li><li>会话 <strong>没有被锁定</strong>，也就是说，用户可以使用该会话。</li></ol><p>然后你可以尝试从客户端连接到该会话：</p><ol><li>启动 <strong>Remmina</strong>。</li><li>在地址栏左侧的下拉菜单中选择 <strong>VNC</strong> 协议。</li><li>在地址栏中输入服务器的IP地址，然后按下 <strong>回车</strong>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/remmina.png" alt="Remmina Window"></li><li>当连接开始时，会打开另一个连接窗口。根据服务器的设置，你可能需要等待，直到服务器用户允许连接，或者你可能需要提供密码。</li><li>输入密码，然后按 <strong>OK</strong>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/remmina_connected_client.png" alt="Remmina Connected to Server"></li><li>按下 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/resolution.png" alt="Align with resolution button"> 调整连接窗口的大小，使之与服务器的分辨率一致，或者按 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/full_screen.png" alt="Full Screen Button"> 调整连接窗口的大小，使其覆盖整个桌面。当处于全屏模式时，注意屏幕上边缘的白色窄条。那是 Remmina 菜单，当你需要离开全屏模式或改变一些设置时，你可以把鼠标移到它上面。</li></ol><p>当你回到服务器时，你会注意到现在在上栏有一个黄色的图标，这表明你正在 Gnome 中共享电脑屏幕。如果你不再希望共享屏幕，你可以进入菜单，点击 <ruby>屏幕正在被共享<rt>Screen is being shared</rt></ruby>，然后再选择 <ruby>关闭<rt>Turn off</rt></ruby>，立即停止共享屏幕。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2022/01/turn_off_connection.png" alt="Turn off menu item"></p><h4 id="会话锁定时终止屏幕共享" tabindex="-1">会话锁定时终止屏幕共享 <a class="header-anchor" href="#会话锁定时终止屏幕共享" aria-label="Permalink to “会话锁定时终止屏幕共享”">​</a></h4><p>默认情况下，当会话锁定时，连接 <ruby>将总是终止<rt>will always terminate</rt></ruby>。在会话被解锁之前，不能建立新的连接。</p><p>一方面，这听起来很合理。如果你想和别人分享你的屏幕，你可能不想让他们在你不在的时候使用你的电脑。另一方面，如果你想从远程位置控制你自己的电脑，无论是你在另一个房间的床上，还是你岳母的地方，同样的方法也不是很有用。有两个选项可以处理这个问题。你可以完全禁止锁定屏幕，或者使用支持通过 VNC 连接解锁会话的 Gnome 扩展。</p><h5 id="禁用屏幕锁定" tabindex="-1">禁用屏幕锁定 <a class="header-anchor" href="#禁用屏幕锁定" aria-label="Permalink to “禁用屏幕锁定”">​</a></h5><p>要禁用屏幕锁定：</p><ol><li>打开 <ruby>Gnome 控制中心<rt>Gnome Control Center</rt></ruby>。</li><li>点击 <ruby>隐私<rt>Privacy</rt></ruby>标签。</li><li>选择 <ruby>屏幕锁定<rt>Screen Lock</rt></ruby> 设置。</li><li>关掉 <ruby>自动屏幕锁定<rt>Automatic Screen Lock</rt></ruby>。</li></ol><p>现在，会话将永远不会被锁定（除非你手动锁定），所以它能启动一个 VNC 连接到它。</p><h5 id="使用-gnome-扩展来允许远程解锁会话" tabindex="-1">使用 Gnome 扩展来允许远程解锁会话 <a class="header-anchor" href="#使用-gnome-扩展来允许远程解锁会话" aria-label="Permalink to “使用 Gnome 扩展来允许远程解锁会话”">​</a></h5><p>如果你不想关闭锁定屏幕的功能，或者你想有一个远程解锁会话的选项，即使它被锁定，你将需要安装一个提供这种功能的扩展，因为这种行为是默认不允许的。</p><p>要安装该扩展：</p>`,44)),i("ol",null,[i("li",null,[t[1]||(t[1]=n("打开",-1)),t[2]||(t[2]=i("strong",null,"火狐浏览器",-1)),t[3]||(t[3]=n("，并打开 ",-1)),r(e,{href:"https://extensions.gnome.org"},{default:s(()=>[...t[0]||(t[0]=[n("Gnome 扩展页面",-1)])]),_:1}),t[4]||(t[4]=n("。 ",-1)),t[5]||(t[5]=i("img",{src:"https://fedoramagazine.org/wp-content/uploads/2022/01/extensions.png",alt:"Gnome Extensions Page"},null,-1))]),t[6]||(t[6]=a('<li>在页面的上部，找到一个信息块，告诉你为火狐安装 “GNOME Shell integration”。</li><li>点击 <ruby>点此安装浏览器扩展<rt>Click here to install browser extension</rt></ruby> 来安装 Firefox 扩展。</li><li>安装完毕后，注意到 Firefox 的菜单部分有 Gnome 的标志。</li><li>点击 Gnome 标志，回到扩展页面。</li><li>搜索 “allow locked remote desktop”。</li><li>点击显示的项目，进入该扩展的页面。</li><li>使用右边的<strong>开/关</strong>按钮，将扩展<strong>打开</strong>。 <img src="https://fedoramagazine.org/wp-content/uploads/2022/01/switch_on_extension.png" alt="Extension selected"></li>',7))]),t[23]||(t[23]=a('<p>现在，可以在任何时候启动 VNC 连接。注意，你需要知道会话密码以解锁会话。如果你的 VNC 密码与会话密码不同，你的会话仍然受到 <em>一点</em> 保护。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>这篇文章介绍了在 Gnome 中实现共享计算机屏幕的方法。它提到了受限（<em>仅浏览</em>）访问和非受限（<em>完全</em>）访问之间的区别。然而，对于正式任务的远程访问，例如管理一个生产服务器，这个解决方案无论如何都不算是一个正确的方法。为什么？</p><ol><li>服务器将始终保持其<strong>控制模式</strong>。任何在服务器会话中的人都将能够控制鼠标和键盘。</li><li>如果会话被锁定，从客户端解锁也会在服务器上解锁。它也会把显示器从待机模式中唤醒。任何能看到你的服务器屏幕的人都能看到你此刻正在做什么。</li><li>VNC 协议本身没有加密或保护，所以你通过它发送的任何东西都可能被泄露。</li></ol><p>你几种可以建立一个受保护的 VNC 连接的方法。例如，你可以通过 SSH 协议建立隧道，以提高安全性。然而，这些都超出了本文的范围。</p><p><strong>免责声明</strong>：上述工作流程在 Fedora 35 上使用几个虚拟机工作时没有问题。如果它对你不起作用，那么你可能遇到了一个错误。请报告它。</p><hr>',7)),i("p",null,[t[8]||(t[8]=n("via: ",-1)),r(e,{href:"https://fedoramagazine.org/sharing-the-computer-screen-in-gnome/"},{default:s(()=>[...t[7]||(t[7]=[n("https://fedoramagazine.org/sharing-the-computer-screen-in-gnome/",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=n("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/lruzicka/"},{default:s(()=>[...t[9]||(t[9]=[n("Lukáš Růžička",-1)])]),_:1}),t[14]||(t[14]=n(" 选题：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[10]||(t[10]=[n("lujun9972",-1)])]),_:1}),t[15]||(t[15]=n(" 译者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[11]||(t[11]=[n("geekpi",-1)])]),_:1}),t[16]||(t[16]=n(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[12]||(t[12]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[19]||(t[19]=n("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[17]||(t[17]=[n("LCTT",-1)])]),_:1}),t[20]||(t[20]=n(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:s(()=>[...t[18]||(t[18]=[n("Linux中国",-1)])]),_:1}),t[21]||(t[21]=n(" 荣誉推出",-1))])])}const x=o(m,[["render",d]]);export{C as __pageData,x as default};
